fn solve() {
    let n: usize = get();
    let mut k: i64 = get();
    // A -> false, B -> true
    let mut s: Vec<bool> = get_word().chars().map(|x| x == 'B').collect();
    assert_eq!(s.len(), n);
    let mut pos = 0;
    for i in 0 .. n {
        s[i] = s[i] ^ ((n + i) % 2 != 1);
    }
    for _ in 0 .. n {
        s.push(false);
    }
    while k > 0 {
        if pos >= n {
            break;
        }
        if s[pos] ^ (n % 2 != 1) { // B
            pos += 1;
        } else { // A
            s[pos] = !s[pos];
        }
        k -= 1;
    }
    if k > 0 && n % 2 == 1 && k % 2 == 1 {
        assert_eq!(pos, n);
        s[n] = !s[n];
    }
    // recons
    let mut out = String::new();
    for i in 0 .. n {
        out.push(if s[pos + i] ^ ((n + i) % 2 != 1) { 'B' } else { 'A' });
    }
    println!("{}", out);
