fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let m: usize = sc.read();
    let d: Vec<u64> = sc.vec(n);
    let mut graph = vec![vec![]; n];
    for i in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push((b, i));
        graph[b].push((a, i));
    }

    let mut tree = vec![vec![]; n];
    let mut ans = vec![1e9 as u64; m];
    for i in 0..n {
        let (_, j, e) = graph[i].iter().map(|&(i, e)| (d[i], i, e)).min().unwrap();
        if d[i] < d[j] {
            println!("-1");
            return;
        }
        tree[i].push(j);
        tree[j].push(i);
        ans[e] = d[i];
    }

    let mut c = vec![0; n];
    for i in 0..n {
        if c[i] == 0 {
            continue;
        }
        c[i] = 1;
        color(i, &tree, &mut c);
    }

    for c in c.into_iter() {
        sc.write(if c == 1 { "W" } else { "B" });
    }
    sc.write("\n");
    for ans in ans.into_iter() {
        sc.write(ans);
        sc.write("\n");
    }
}

fn color(v: usize, tree: &Vec<Vec<usize>>, c: &mut Vec<usize>) {
    for &next in tree[v].iter() {
        if c[next] == 0 {
            c[next] = if c[v] == 1 { 2 } else { 1 };
            color(next, tree, c);
        } else {
            assert_ne!(c[v], c[next]);
        }
    }
}

