use std::collections::BinaryHeap;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };

    let n = sc.read();
    let a: Vec<u64> = sc.vec(n);
    let mut b: Vec<u64> = sc.vec(n);
    if (0..n).any(|i| a[i] >= b[i]) {
        println!("-1");
        return;
    }

    let mut ans = 0;
    let mut heap = BinaryHeap::new();
    for i in 0..n {
        push(&mut heap, &a, &b, i);
    }

    while let Some((_, i)) = heap.pop() {
        let prev = b[(n + i - 1) % n];
        let next = b[(i + 1) % n];
        let d = b[i] - a[i];
        ans += d / (prev + next);
        //        let diff = d / (prev + next) * (prev + next);
        //        b[i] -= diff;
        b[i] = (b[i] - a[i]) & (prev + next) + a[i];
        push(&mut heap, &a, &b, (i + 1) % n);
        push(&mut heap, &a, &b, (n + i - 1) % n);
    }

    if a != b {
        println!("-1");
    } else {
        println!("{}", ans);
    }
}

fn push(heap: &mut BinaryHeap<(u64, usize)>, a: &Vec<u64>, b: &Vec<u64>, i: usize) {
    let n = b.len();
    let prev = b[(n + i - 1) % n];
    let next = b[(i + 1) % n];
    let d = b[i] - a[i];
    let effect = d / (prev + next);
    if effect > 0 {
        heap.push((effect, i));
    }
}

