fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { reader: s.lock() };
    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut graph = vec![vec![]; n];
    let mut ins = vec![0; n];
    for _ in 0..(n - 1 + m) {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        ins[b] += 1;
    }

    let mut root = n;
    for i in 0..n {
        if ins[i] == 0 {
            root = i;
        }
    }

    let mut parents = vec![n; n];
    let mut q = VecDeque::new();
    q.push_back(root);
    while let Some(v) = q.pop_front() {
        for &next in graph[v].iter() {
            if next == root || parents[next] != n {
                continue;
            }
            parents[next] = v;
            q.push_back(next);
        }
    }
    for i in 0..n {
        if i != root {
            println!("{}", parents[i] + 1);
        } else {
            println!("0");
        }
    }
}

