use std::io::BufRead;

fn enough(hs: &[usize], a: usize, b: usize, count: usize) -> bool{
    let mut attack = 0;
    // 最大ダメージはb * count + a * a_i
    // ただし Sum(a_i) <= count
    // min a_i = (hs[i] - b * count) / (a - b) (+ 1 割り切れなかったら)
