use std::io::prelude::*;
use std::collections::HashMap;

fn main() {
    let _ = get_line();
    let mut initials: HashMap<char, i64> = HashMap::new();
    for name in get_lines() {
        *initials.entry(name.chars().next().unwrap()).or_insert(0) += 1;
    }
    println!("{}", solve(&initials));
}

fn solve(initials: &HashMap<char, i64>) -> i64 {
    let nums: Vec<i64> = "MARCH"
        .chars()
        .map(|c| *initials.get(&c).unwrap_or(&0))
        .collect();
    let mut ans = 0;
    for group in combs(&nums, 3) {
        ans += group.iter().fold(1, |a, v| a * v);
    }
    ans
}

fn combs<T: Clone + std::fmt::Debug>(v: &[T], n: usize) -> Vec<Vec<T>> {
    if n == 0 {
        return vec![vec![]];
    }
    // v.iter.enumerate.take.map(recur).fold would be nice..
    let mut gen = vec![];
    for (i, val) in v.iter().enumerate().take(v.len() - n + 1) {
        for mut sub in combs(&v[i + 1..], n - 1) {
            sub.push(val.clone());
            gen.push(sub);
        }
    }
    gen
}

fn get_lines() -> Vec<String> {
    let stdin = io::stdin();
    let lock = stdin.lock();
    let lines = lock.lines().map(|l| l.unwrap()).collect(); // for lifetime?
    lines
}

fn get_line() -> String {
    let mut inp = String::new();
    io::stdin().read_line(&mut inp).expect("read error");
    inp.trim().to_string()
}
