fn ulog2(u: u32) -> u32 {
    return (u as f64).log2().floor() as u32;
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, l: u32);
    let r = (l as f64).log2().floor() as u32;
    let mut ret = vec![];
    for i in 0..r {
        ret.push(format!("{} {} {}", i + 1, i + 2, 0));
        ret.push(format!("{} {} {}", i + 1, i + 2, 2usize.pow(i as u32)));
    }
    let mut cur = 2u32.pow(r);
    while cur <= l {
        let t = ulog2(l + 1 - cur);
        ret.push(format!("{} {} {}", t + 1, r + 1, cur));
        cur += 2u32.pow(t);
    }
    println!("{} {}", r + 1, ret.len());
    for line in ret {
        println!("{}", line);
    }
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

