fn merge(vec: &mut Vec<i32>, left: usize, mid: usize, right: usize) -> i64 {
  let n1 = mid - left;
  let n2 = right - mid;
  let mut l = Vec::with_capacity(n1 + 1);
  let mut r = Vec::with_capacity(n2 + 1);
  for i in 0..n1 {
    l.push(vec[left + i]);
  }
  for i in 0..n2 {
    r.push(vec[mid + i]);
  }
  l.push(std::i32::MAX);
  r.push(std::i32::MAX);
  let mut ans = 0;
  let (mut i, mut j) = (0, 0);
  for k in left..right {
    if l[i] <= r[j] {
      vec[k] = l[i];
      i += 1;
    }
    else {
      vec[k] = r[j];
      j += 1;
      ans += l.len() - 1 - i;
    }
  }
  ans as i64
}

fn merge_sort(vec: &mut Vec<i32>, left: usize, right: usize) -> i64 {
  let mut ans = 0;
  if left + 1 < right {
    let mid = (left + right) / 2;
    ans += merge_sort(vec, left, mid);
    ans += merge_sort(vec, mid, right);
    ans += merge(vec, left, mid, right);
  }
  ans
}

