fn permutations(vec: &[usize]) -> Vec<Vec<usize>> {
    if let Some((n, rest)) = vec.split_first() {
        let prev = permutations(rest);
        prev.iter()
            .flat_map(|p| {
                let mut next = vec![];
                for (i, _) in p.iter().enumerate() {
                    let mut q = p.clone();
                    q.insert(i, *n);
                    next.push(q)
                }
                next
            })
            .collect()
    } else {
        vec![vec![]]
    }
}

