        graph[a - 1][b - 1] = c;
        graph[b - 1][a - 1] = c;
    }
    for i in 0..n {
        graph[i][i] = 0
    }

    for k in 0..n {
        for i in 0..n {
            for j in 0..n {
                let dist = graph[i][k] + graph[k][j];
                if graph[i][j] > dist {
                    graph[i][j] = dist;
                }
            }
        }
