use std::io;
use std::collections::VecDeque;

fn main() {
    println!("{}", solve());
}

fn solve() -> String {
    let mut input = Input::new();
    let n: usize = input.next();
    let mut a: Vec<usize> = (0..n).map(|_| input.next()).collect();
    a.sort();
    if n > 3 && a[0] == a[2] {
        return String::from("Impossible");
    }
    let m = a[0];
    let x = m - if m < a[1] { 0 } else { 1 };
    let mut c = vec![0; n];
    for v in a {
        c[v] += 1;
    }
    for i in 0..n {
        if i == m {
            continue;
        }
        if (i < m || m + x < i) && c[i] > 0 {
            return String::from("Impossible");
        }
        if !(i < m || m + x < i) && c[i] < 2 {
            return String::from("Impossible");
        }
    }
    String::from("Possible")
}

struct Input {
    queue: VecDeque<String>,
}

impl Input {
    fn new() -> Input {
        Input { queue: VecDeque::new() }
    }

    fn next<T>(&mut self) -> T
        where T: std::str::FromStr,
              T::Err: std::fmt::Debug
    {
        if self.queue.is_empty() {
            let mut line = String::new();
            let _ = io::stdin().read_line(&mut line);
            for x in line.split_whitespace() {
                self.queue.push_back(String::from(x));
            }
        }
        return self.queue.pop_front().unwrap().parse::<T>().unwrap();
    }
}
