fn primes(n: usize) -> Vec<bool> {
    let mut is_prime = vec![true; n + 1];

    if n >= 1 {
        is_prime[1] = false;
    }
    let mut i = 2;
    while i * i <= n {
        if is_prime[i] {
            let mut cur = i * i;
            while cur < n {
                is_prime[cur] = false;
                cur += i;
            }
        }
        i += 1;
    }
    is_prime
}

