fn scan<'a, I: Iterator<Item = &'a str>, T: std::str::FromStr>(tokens: &mut I) -> T {
    tokens.next().unwrap().parse().ok().unwrap()
}

fn main() {
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let n: usize = scan(tokens);
    let k: usize = scan(tokens);
    if k % 2 == 1 || k > n * n / 2 {
        println!("0");
        return;
    }
    let k: usize = k / 2;
    let modulo: usize = 1_000_000_007;
    let mut dp: Vec<Vec<Vec<usize>>> = vec![vec![vec![0; k + 1]; n + 1]; 2];
    dp[0][0][0] = 1;
    for i in 1..n + 1 {
        for j in 0..i + 1 {
            for x in 0..k + 1 {
                let mut tmp: usize = 0;
                if x >= j {
                    if j > 0 {
                        tmp += dp[(i - 1) & 1][j - 1][x - j];
                    }
                    tmp += (2 * j + 1) * dp[(i - 1) & 1][j][x - j];
                    if j < n {
                        tmp += (j + 1) * (j + 1) * dp[(i - 1) & 1][j + 1][x - j];
                    }
                }
                dp[i & 1][j][x] = tmp % modulo;
            }
        }
    }
    println!("{}", dp[n & 1][0][k]);
