use std::io::{BufRead, Write};

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut buf = String::new();
    input.read_line(&mut buf).unwrap();
    let _n: usize = buf.trim_right().parse().unwrap();
    buf.clear();
    input.read_line(&mut buf).unwrap();
    let x: Vec<usize> = buf.split_whitespace().map(|s| s.parse().unwrap()).collect();
    let mut sorted = x.clone();
    sorted.sort();
    let half = x.len() / 2;
    for item in &x {
        let idx = sorted.binary_search(item).unwrap();
        writeln!(
            output,
            "{}",
            if idx < half {
                sorted[half]
            } else {
                sorted[half - 1]
            }
        ).unwrap();
    }
}

