    for i in 0..n {
        let c = if s[i] == '1' as u8 { 1 } else { 0 };
        imos[i+1] = imos[i] + c;
    }

    let mut maxto: Vec<usize> = vec![0; n];
    for &(fr, to) in &lr {
        maxto[fr-1] = max(maxto[fr-1], to);
    }

    let mut dp: Vec<Vec<i64>> = vec![vec![0; n+1]; n+1];
    dp[0][0] = 1;

    let mut prev = vec![0; n+1];
    let mut to = 0;
    for i in 0..n {
        to = max(to, i);
        let mut h = 0;
        if to < maxto[i] {
            h += imos[maxto[i]] - imos[to];
        }
        to = max(to, maxto[i]);

        for j in 0..n+1 {
            if j >= h {
                prev[j] = dp[i][j-h];
            }  else {
                prev[j] = 0;
            }
        }

        let size = to - i;
        if size == 0 {
            for j in 0..n+1 {
                dp[i+1][j] = dp[i][j];
            }
        } else {
            for j in 0..n+1 {
                let left_zero = size - j;
                let left_one = j;
                let base = prev[j];
                if base >= 1 {
                    if left_zero >= 1 {
                        dp[i+1][j] += base;
                        dp[i+1][j] %= MOD;
                    }
                    if left_one >= 1 {
                        dp[i+1][j-1] += base;
                        dp[i+1][j-1] %= MOD;
                    }
                }
            }
        }
    }

    let mut ans = 0;
    for i in 0..n+1 {
        ans += dp[n][i];
    }
