fn run() {
    input! {
        n: usize,
        p: [usize1; n - 1],
        x: [usize; n],
    }
    let mut child = vec![vec![]; n];
    for (i, &p) in p.iter().enumerate() {
        child[p].push(i + 1);
    }
    let mut min = vec![0; n];
    for (v, &w) in x.iter().enumerate().rev() {
        let mut sum = 0;
        let mut dp = vec![false; w + 1];
        dp[0] = true;
        for &u in child[v].iter() {
            sum += x[u] + min[u];
            let mut next = vec![false; w + 1];
            for i in 0..(w + 1) {
                if i + x[u] <= w {
                    next[i + x[u]] |= dp[i];
                }
                if i + min[u] <= w {
                    next[i + min[u]] |= dp[i];
                }
            }
            dp = next;
        }
        match dp.iter().rposition(|x| *x) {
            Some(k) => {
                min[v] = sum - k;
            },
            None => {
                println!("IMPOSSIBLE");
                return;
            },
        }
    }
    println!("POSSIBLE");
}

fn main() {
    run();
}
