fn solve(mut aa: Vec<i64>) -> Vec<i64> {
    use std::cmp::min;

    let n = aa.len();
    aa.insert(0, 0);
    aa.push(0);
    println!("{:?}", aa);
    let sum = aa.iter().fold((0,0), |(sum, p), a| (sum + (p-a).abs(), *a) ).0;

    (1..(n+1)).map(|i| {
        if (aa[i-1] <= aa[i] && aa[i] <= aa[i+1]) ||
            (aa[i+1] <= aa[i] && aa[i] <= aa[i-1])
        {
            sum
        } else {
            sum - (2*min((aa[i-1] - aa[i]).abs(), (aa[i+1]-aa[i]).abs()))
        }
    }).collect::<Vec<_>>()
}

