fn read_stdin() -> String {
    use std::io::Read;
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).unwrap();
    input
}

fn scan<'a, I: Iterator<Item = &'a str>, T: std::str::FromStr>(tokens: &mut I) -> T {
    tokens.next().unwrap().parse().ok().unwrap()
}

fn vec<T, F: FnMut(usize) -> T>(n: usize, mut f: F) -> Vec<T> {
    (0..n).map(|i| f(i)).collect()
}

fn main() {
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let n: usize = scan(tokens);
    let mut neighbors: Vec<Vec<usize>> = vec![Vec::new(); n];
    for _ in 0..n - 1 {
        let a: usize = scan(tokens);
        let b: usize = scan(tokens);
        neighbors[a - 1].push(b - 1);
        neighbors[b - 1].push(a - 1);
    }
    let mut parent: Vec<usize> = (0..n).collect();
    let mut children: Vec<usize> = vec![0; n];
    fn dfs(
        i: usize,
        p: usize,
        neighbors: &Vec<Vec<usize>>,
        parent: &mut Vec<usize>,
        children: &mut Vec<usize>,
    ) {
        parent[i] = p;
        children[i] = 1 << i;
        for &j in &neighbors[i] {
            if j != p {
                dfs(j, i, neighbors, parent, children);
                children[i] |= children[j];
            }
        }
    }
    dfs(0, 0, &neighbors, &mut parent, &mut children);
    let m: usize = scan(tokens);
    let paths: Vec<usize> = vec(m, |_| {
        let u: usize = scan(tokens);
        let v: usize = scan(tokens);
        let mut u = u - 1;
        let mut v = v - 1;
        let mut p = 0;
        while children[u] & (1 << v) == 0 {
            p |= 1 << u;
            u = parent[u];
        }
        while u != v {
            p |= 1 << v;
            v = parent[v];
        }
        p
    });
    fn rec(paths: &[usize], set: usize, all: usize) -> i64 {
        if paths.is_empty() {
            1 << (all ^ set).count_ones()
        } else {
            rec(&paths[1..], set, all) - rec(&paths[1..], set | paths[0], all)
        }
    }
    println!("{}", rec(&paths, 0, (1 << n) - 2));
}
