use std::io::Write;
use std::cmp::*;

fn run() {
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    input! {
        x: i64,
        n: usize,
        r: [i64; n],
        q: usize,
        p: [(i64, i64); q],
    }
    #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
    enum Event {
        Flip,
        Ask(i64, usize),
    }
    let mut e = vec![];
    for r in r.into_iter() {
        e.push((r, Event::Flip));
    }
    for (i, (t, a)) in p.into_iter().enumerate() {
        e.push((t, Event::Ask(a, i)));
    }
    e.sort();
    let mut ans = vec![0; q];
    let mut prev = 0;
    let mut diff = 0;
    let mut range = (0, x);
    let mut val = (0, x);
    let mut sign = -1;
    for (t, e) in e.into_iter() {
        let add = sign * (t - prev);
        prev = t;
        diff += add;
        val.0 = min(max(val.0 + add, 0), x);
        val.1 = min(max(val.1 + add, 0), x);
        range.0 = max(range.0, -diff);
        range.1 = min(range.1, x - diff);
        match e {
            Event::Flip => {
                sign *= -1;
            },
            Event::Ask(a, k) => {
                if range.0 <= a && a <= range.1 {
                    ans[k] = a + diff;
                } else if a < range.0 {
                    ans[k] = val.0;
                } else {
                    ans[k] = val.1;
                }
            },
        }
    }
    for a in ans {
        writeln!(out, "{}", a).ok();
    }
}

fn main() {
    run();
}
