fn solve(
    cur: usize,
    par: Option<usize>,
    color: usize,
    graph: &Vec<Vec<usize>>,
    dp: &mut Vec<Vec<Option<usize>>>,
) -> usize {
    if dp[cur][color].is_some() {
        return dp[cur][color].unwrap();
    }
    let mut res = 1;
    for &to in &graph[cur] {
        if par.is_some() && par.unwrap() == to {
            continue;
        }
        let mut next = 0;
        next += solve(to, Some(cur), 1, graph, dp);
        if color == 1 {
            next += solve(to, Some(cur), 0, graph, dp);
        }
        next %= M;

        res *= next;
        res %= M;
    }

    dp[cur][color] = Some(res);
