    fn rec(n: usize, m: usize, i: usize, j: usize, res: &mut Vec<Vec<bool>>) {
        if n == 1 {
            for y in 1..1 << m {
                res[i + 1][j + y] = true;
            }
        } else if m == 1 {
            for x in 1..1 << n {
                res[i + x][j + 1] = true;
            }
        } else {
            let x = i + (1 << (n - 1));
            let y = j + (1 << (m - 1));
            res[x][y] = true;
            rec(n - 1, m - 1, i, j, res);
            rec(n - 1, m - 1, i, y, res);
            rec(n - 1, m - 1, x, j, res);
            rec(n - 1, m - 1, x, y, res);
