fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut s = String::new();
    input.read_line(&mut s).unwrap();
    let mut split = s.split_whitespace();
    let n = split.next().unwrap().parse::<u32>().unwrap();
    let m = split.next().unwrap().parse::<u32>().unwrap();
    let mut s = String::new();
    let mut colors = vec![(0u32,-1i32);n as usize];
    let mut adjacency = vec![Vec::<u32>::new();n as usize];
    for _ in 0..m {
        s.clear();
        input.read_line(&mut s).unwrap();
        let mut split = s.split_whitespace();
        let a = split.next().unwrap().parse::<u32>().unwrap();
        let b = split.next().unwrap().parse::<u32>().unwrap();
        adjacency[a as usize - 1].push(b - 1);
        adjacency[b as usize - 1].push(a - 1);
    }
    s.clear();
    input.read_line(&mut s).unwrap();
    let q = s.trim().parse::<usize>().unwrap();
    let vdc = (0..q)
        .map(|_| {
            s.clear();
            input.read_line(&mut s).unwrap();
            let mut split = s.split_whitespace();
            let v = split.next().unwrap().parse::<u32>().unwrap();
            let d = split.next().unwrap().parse::<i32>().unwrap();
            let c = split.next().unwrap().parse::<u32>().unwrap();
            (v, d, c)
        })
        .collect::<Vec<_>>();
    for (v, d, c) in vdc.into_iter().rev() {
        paint(&mut colors, v as usize - 1, c, d, &adjacency);
    }
    for (c, _) in colors {
        writeln!(output, "{}", c).unwrap();
    }
}

