        println!("4 5");
        println!("5 6");
        return;
    }

    let w = (n + 1) / 4 * 4 - 1;
    let mut used = vec![false; n];
    let mut ans = vec![];
    let mut row = vec![];
    row.push(w);
    row.push(1);
    if w != 3 {
        row.push(3);
    }
    row.push(2);
    if n % 4 == 0 {
        let mut head = 0;
        let mut tail = 0;
        for i in 0..30 {
            if (1 << i) & n != 0 {
                used[1 << i] = true;
                row.push(1 << i);
                if head == 0 {
                    head = 1 << i;
                }
                tail = 1 << i;
            }
        }
        ans.push((head, n));
        ans.push((tail, n + n));
    }
    for i in 4..w {
        if used[i] {
            continue;
        }
        row.push(i);
