fn solve<R: BufRead, W: Write>(stdin: &mut R, stdout: &mut BufWriter<W>) {
    let ell = stdin.gets().parse::<usize>().unwrap();
    let mut n = 0;
    while (1 << n) <= ell {
        n += 1;
    }
    let base = (1 << n - 1) - 1;
    let mut edges = Vec::new();
    for i in 0..n - 1 {
        edges.push((i, i + 1, 0));
        edges.push((i, i + 1, 1 << i));
    }
    let mut rem = ell - 1 - base;
    let mut i = 0;
    let mut next = base + 1;
    while rem > 0 {
        if rem % 2 == 1 {
            edges.push((i, n - 1, next));
            next += 1 << i;
        }
        rem /= 2;
        i += 1;
    }
    writeln!(stdout, "{} {}", n, edges.len()).unwrap();
    for (f, t, c) in edges {
        writeln!(stdout, "{} {} {}", f + 1, t + 1, c).unwrap();
    }
}

