fn dfs(adj: &Vec<Vec<(usize, usize)>>, a: usize, b: usize, prev: usize) -> i64 {
  let mut ans = 0;
  for &(v, i) in &adj[a] {
    if v == prev {
      continue;
    }
    if v == b {
      return 1 << i as i64;
    }
    let ret = dfs(adj, v, b, a);
    if ret != 0 {
      return ret | (1 << i as i64);
    }
  }
  return 0;
}

fn main() {
  let out = std::io::stdout();
  let mut out = std::io::BufWriter::new(out.lock());
