    n: usize,
    es: [(usize1, usize1); n-1],
    m: usize,
    cs: [(usize1, usize1); m],
  }
  let mut adj = vec![vec![]; n];
  for (i, &(a, b)) in es.iter().enumerate() {
    adj[a].push((b, i));
    adj[b].push((a, i));
  }
  let mut path = vec![0i64; m];
  for (i, &(a, b)) in cs.iter().enumerate() {
    path[i] = dfs(&adj, a, b, n);
  }
  let mut ans = 1i64 << (n - 1);
  for pat in 0 .. 1 << m {
    let mut white = 0;
    let mut count = 0;
    for (i, &p) in path.iter().enumerate() {
      if (pat >> i) & 1 == 0 {
        continue;
      }
      count += 1;
      white |= p;
    }
    let mut popl = 0;
    for i in 0 .. n {
      if (white >> i) & 1 != 0 {
        popl += 1;
      }
    }
    if count % 2 == 1 {
      ans -= 1 << (n - 1 - popl);
    } else {
      ans += 1 << (n - 1 - popl);
    }
  }

  puts!("{}\n", ans);
}
