fn floor_sum(n: i64, m: i64, mut a: i64, mut b: i64) -> i64 {
    let mut res = 0;
    if a >= m {
        res += (n - 1) * n * (a / m) / 2;
        a %= m;
    }
    if b >= m {
        res += n * (b / m);
        b %= m;
    }

    let y_max = (a * (n - 1) + b) / m;
    if y_max == 0 { return res; }
    let x_max = y_max * m - b;
    res += (n - (x_max + a - 1) / a) * y_max;
    res + floor_sum(y_max, a, m, (a - x_max % a) % a)
}

