fn scan<'a, I: Iterator<Item = &'a str>, T: std::str::FromStr>(tokens: &mut I) -> T {
    tokens.next().unwrap().parse().ok().unwrap()
}

fn main() {
    use std::collections::HashMap;
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let n: i64 = scan(tokens);
    let x: i64 = scan(tokens);
    let d: i64 = scan(tokens);
    if d == 0 {
        if x == 0 {
            println!("{}", 0);
        } else {
            println!("{}", n + 1);
        }
        return;
    }
    let (x, d) = if d < 0 { (x + (n - 1) * d, -d) } else { (x, d) };
    let mut intervals = HashMap::new();
    for k in 0..n + 1 {
        let mut m = k * x % d;
        if m < 0 {
            m += d;
        }
        let a = (k * x - m) / d + k * (k - 1) / 2;
        let b = (k * x - m) / d + k * ((n - k) + (n - 1)) / 2;
        intervals.entry(m).or_insert_with(Vec::new).push((a, b));
    }
    let mut ans = 0;
    for v in intervals.values_mut() {
        v.sort();
        let mut x = std::i64::MIN;
        let mut y = std::i64::MIN;
        for &(a, b) in v.iter() {
            if y < a {
                ans += y - x;
                x = a;
                y = b;
            } else {
                x = std::cmp::min(x, a);
                y = std::cmp::max(y, b);
            }
        }
        ans += y - x;
    }
    println!("{}", ans);
}
