use std::collections::VecDeque;

const INF: i64 = 1e9 as i64;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let m: usize = sc.read();
    let d: Vec<i64> = sc.vec(n);
    let mut graph = vec![vec![]; n];
    for i in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push((b, i));
        graph[b].push((a, i));
    }

    let mut tree = vec![vec![]; n];
    let mut edges = vec![INF; m];
    for i in 0..n {
        let mut candidates = graph[i]
            .iter()
            .map(|&(next, edge_id)| (d[next], next, edge_id))
            .collect::<Vec<_>>();
        candidates.sort();
        let (_, next, edge_id) = candidates[0];
        if d[next] > d[i] {
            println!("-1");
            return;
        }

        tree[i].push(next);
        tree[next].push(i);
        edges[edge_id] = d[i];
    }

    let mut color = vec![0; n];
    for i in 0..n {
        if color[i] != 0 {
            continue;
        }
        let mut q = VecDeque::new();
        q.push_back(i);
        color[i] = 1;
        while let Some(v) = q.pop_front() {
            for &next in tree[v].iter() {
                if color[next] == 0 {
                    color[next] = if color[v] == 1 { 2 } else { 1 };
                    q.push_back(next);
                } else {
                    assert_ne!(color[next], color[v]);
                }
            }
        }
    }

    for i in 0..n {
        if color[i] == 1 {
            sc.write("W");
        } else {
            sc.write("B");
        }
    }
    sc.write("\n");
    for edge in edges.into_iter() {
        sc.write(edge);
        sc.write("\n");
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}
