fn counts(a: &[usize]) -> Vec<usize> {
    let mut rs = Vec::with_capacity(a.len() + 1);

    rs.push(0);
    rs.push(0);

    let mut ss = ([0; 16], [0; 16]);
    let mut ss = (&mut ss.0, &mut ss.1);

    for c in 0..ss.0.len() {
        ss.0[c] = c;
    }

    for i in 1..a.len() {
        let mut d = 0isize;
        let mut a0 = a[i - 1];
        let mut a1 = a[i];
        while a0 < a1 {
            a0 *= 4;
            d += 1;
        }
        while a0 >= a1 * 4 {
            a1 *= 4;
            d -= 1;
        }
        for c in 0..ss.1.len() {
            let mut c_next = max(c as isize + d, 0) as usize;
            let mut r = c;
            if c_next >= ss.0.len() {
                let d = c_next - ss.0.len() + 1;
                c_next -= d;
                r += i * d;
            }
            ss.1[c] = r + ss.0[c_next];
        }
        rs.push(ss.1[0]);
        std::mem::swap(&mut ss.0, &mut ss.1);
    }
    rs
}
