struct UnionFind{
    /// 最小構成UnionFind木
    P: Vec<usize>,
}

impl UnionFind {
    fn new(n:usize) -> UnionFind{
        UnionFind {P:(0..n).collect()}
    }
    fn get_parent(&mut self,n:usize) -> usize{
        if self.P[n] == n{ return n;}
        let p = self.P[n];
        self.P[n] = self.get_parent(p);
        self.P[n]
    }
    fn is_unite(&mut self,x:usize,y:usize) -> bool{
        self.get_parent(x)==self.get_parent(y)
    }
    fn merge(&mut self,x:usize,y:usize){
        if self.is_unite(x,y) {return;}
        let i = self.get_parent(x);
        let j = self.get_parent(y);
        self.P[j] = i;
    }
}

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace();
    let N:usize = iter.next().unwrap().parse().unwrap();
    let K:usize = iter.next().unwrap().parse().unwrap();
    let L:usize = iter.next().unwrap().parse().unwrap();
    let mut T1 = UnionFind::new(N);
    for _ in 0..K{
        let p:usize = iter.next().unwrap().parse::<usize>().unwrap() -1;
        let q:usize = iter.next().unwrap().parse::<usize>().unwrap() -1;
        T1.merge(p,q);
    }
    let mut T2 = UnionFind::new(N);
    for _ in 0..L{
        let p:usize = iter.next().unwrap().parse::<usize>().unwrap() -1;
        let q:usize = iter.next().unwrap().parse::<usize>().unwrap() -1;
        T2.merge(p,q);
    }
    let mut cnt = HashMap::new();
    for i in 0..N{
        let p = T1.get_parent(i);
        let q = T2.get_parent(i);
        let k = (p,q);
        let c = *(cnt.get(&k).unwrap_or(&0));
        cnt.insert(k, c+1);
    }
    for i in 0..N{
        let p = T1.get_parent(i);
        let q = T2.get_parent(i);
        let k = (p,q);
        let ans = cnt.get(&k).unwrap();
        println!("{}",ans);
    }

}
