        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: ty),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, a: [usize; n]);
    let s: Vec<_> = a
        .iter()
        .scan(0, |s, &ai| {
            *s += ai;
            Some(*s)
        })
        .collect();
    let diff = |a, b| if a > b { a - b } else { b - a };
    let mut ab = vec![(std::usize::MAX / 10, 0, 0); n];
    let mut i = 1usize;
    let l = |i, _| s[i - 1];
    let r = |i, j| s[j - 1] - s[i - 1];
    for j in 2..(n - 1) {
        let mut previ = i;
        while r(i, j) > l(i, j) && j - 1 > i {
            previ = i;
            i += 1;
        }
        let mut x = diff(r(i, j), l(i, j));
        let y = diff(r(previ, j), l(previ, j));
        if x > y {
            i = previ;
            x = y;
        }
        ab[j] = (x, r(i, j), l(i, j));
    }

    let mut cd = vec![(std::usize::MAX / 10, 0, 0); n];
    let mut i = 3usize;
    let l = |i, j| s[i - 1] - s[j - 1];
    let r = |i, _| s[n - 1] - s[i - 1];
    for j in 2..(n - 1) {
        while i <= j {
            i += 1;
        }
        let mut previ = i;
        while r(i, j) > l(i, j) && n - 1 > i {
            previ = i;
            i += 1;
        }
        let mut x = diff(r(i, j), l(i, j));
        let y = diff(r(previ, j), l(previ, j));
        if x > y {
            i = previ;
            x = y;
        }
        cd[j] = (x, r(i, j), l(i, j));
    }
    let mut ret = std::usize::MAX;
    for i in 2..(n - 1) {
        let (_, a, b) = ab[i];
        let (_, c, d) = cd[i];
        let m0 = min(a, min(b, min(c, d)));
        let m1 = max(a, max(b, max(c, d)));
        ret = min(ret, diff(m0, m1));
        assert_eq!(a + b + c + d, s[n - 1]);
    }
    println!("{}", ret);
}

