    let mut nedge = vec![0; h + w];
    let mut uf = UnionFind::new(h + w);
    let mut ans = 0;
    for &(r, c, a) in &rca {
        let (r, c) = (r - 1, h + c - 1);
        let pr = uf.find(r);
        let pc = uf.find(c);
        if pr != pc && uf.size[pr] + uf.size[pc] > nedge[pr] + nedge[pc] {
            uf.union(r, c);
            nedge[uf.find(r)] = nedge[pr] + nedge[pc] + 1;
            ans += a as i64;
        } else if pr == pc && uf.size[pr] > nedge[pr] {
            nedge[uf.find(r)] += 1;
            ans += a as i64;
        }
    }

    println!("{}", ans);
