fn binary_search<T: Ord>(low: usize, high: usize, x: T, v: &Vec<T>) -> usize {
    let mid = (low + high) / 2;
    if mid == low {
        return high;
    }

    if v[mid] <= x {
        binary_search(mid, high, x, v)
    } else {
        binary_search(low, mid, x, v)
    }
}
