fn solve(a: Vec<usize>) -> Option<usize> {
    let mut result = 0;
    let mut visited = vec![false; a.len()];
    let mut current = 0;
    visited[0] = true;

    while current != 1 {
        if visited[current] {
            return None;
        } else {
            visited[current] = true;
            current = a[current];
            result += 1;
        }
    }
    Some(result)
