fn sieve_of_Eratosthenes(n: usize) -> Vec<bool> {
    let mut res = vec![true; n];
    if n > 0 {
        res[0] = false;
        if n > 1 {
            res[1] = false;
        }
    }
    let mut i = 2;
    while i*i < n {
        if res[i] {
            let mut j = i*2;
            while j < n {
                res[j] = false;
                j += i;
            }
        }
        i += 1;
    }
    res
}

